 for(const row of current.native_current_selections){exact(row,['snapshot_line_id','scope_id','root_timesheet_id','selected_transition_id','selected_order_key','source_hash','selected_final_revision_id','source_export_present','exclude_cancel'],'REPORT_NATIVE_NONE_SELECTION_INVALID');
